define(["core/ajax","core/templates","core/notification"],function(e,t,r){"use strict";return{init:n=>{const o=document.getElementById(n.rootid);if(!o)return;e.call([{methodname:"block_personalprogress_get_dashboard",args:{courseid:n.courseid,blockinstanceid:n.blockinstanceid}}])[0].then(e=>t.render("block_personalprogress/dashboard",e)).then(e=>(o.innerHTML=e,o.setAttribute("aria-busy","false"),e)).catch(e=>{o.textContent=o.dataset.errorLabel||"",o.setAttribute("aria-busy","false"),r.exception(e)})}}});